<?php $roles=explode(',',$managedUser['roles']??''); ?><section class="page-section"><div class="container narrow"><div class="section-title"><div><p class="eyebrow">QUẢN TRỊ</p><h1>Sửa tài khoản</h1><p>Cập nhật hồ sơ, mật khẩu và vai trò.</p></div></div><form class="surface-card" method="post" action="<?= e(url('/admin/users/'.$managedUser['id'])) ?>"><?= csrf_field() ?><div class="form-row"><div class="form-group col-md-6"><label for="full_name">Họ tên</label><input class="form-control" id="full_name" name="full_name" value="<?= e($managedUser['full_name']) ?>" required></div><div class="form-group col-md-6"><label for="email">Email</label><input class="form-control" id="email" type="email" name="email" value="<?= e($managedUser['email']) ?>" required></div></div><div class="form-row"><div class="form-group col-md-6"><label for="phone">Số điện thoại</label><input class="form-control" id="phone" name="phone" value="<?= e($managedUser['phone']) ?>"></div><div class="form-group col-md-6"><label for="password">Mật khẩu mới (để trống nếu giữ nguyên)</label><input class="form-control" id="password" type="password" name="password" minlength="8"></div></div><fieldset class="form-group"><legend>Vai trò</legend><div class="check-grid"><?php foreach(['guest','host','admin'] as $role): ?><label><input type="checkbox" name="roles[]" value="<?= $role ?>" <?= in_array($role,$roles,true)?'checked':'' ?>> <?= $role ?></label><?php endforeach; ?></div></fieldset><button class="btn btn-primary">Lưu tài khoản</button><a class="btn btn-ghost" href="<?= e(url('/admin')) ?>">Quay lại</a></form></div></section>

